import {
    Table,
    BooleanColumn,
    ChoiceColumn,
    GenericColumn,
    GuidColumn,
    JsonColumn,
    ListColumn,
    ReferenceColumn,
    StringColumn,
    TranslatedTextColumn,
} from '../../db'

export const sys_ux_macroponent = Table({
    actions: {
        read: true,
        update: true,
        delete: true,
        create: true,
    },
    allowClientScripts: false,
    allowNewFields: false,
    allowUiActions: false,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_text_index: true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'UX Macroponent Definition',
    name: 'sys_ux_macroponent',
    schema: {
        root_component_definition: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'JSON Object, specifying the implementation details of the root element for this Macropoent',
                    label: 'Root element metadata',
                    plural: 'Root element metadatas',
                },
            ],
            maxLength: 8000,
        }),
        keyboard_shortcuts: JsonColumn({
            default: '{}',
            label: [
                {
                    hint: "JSON Object where the keys are keyboard shortcut sys ID's and the values are an arrary of event objects.",
                    label: 'Keyboard Shortcuts',
                    plural: 'Keyboard Shortcuts',
                },
            ],
            maxLength: 8000,
        }),
        state_persistence_config: JsonColumn({
            label: [
                {
                    hint: 'JSON Object, specifying the configuration of the state persistence',
                    label: 'State Persistence Config',
                    plural: 'State Persistence Configs',
                },
            ],
            maxLength: 8000,
        }),
        description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: [
                {
                    hint: 'A description of the macroponent',
                    label: 'Description',
                    plural: 'Descriptions',
                },
            ],
            maxLength: 4000,
        }),
        props: JsonColumn({
            label: [
                {
                    hint: 'JSON Object, describing the API for this Macroponent as properties that can be set and read externally',
                    label: 'Properties',
                    plural: 'Properties',
                },
            ],
            maxLength: 8000,
        }),
        required_translations: GenericColumn({
            columnType: 'json_translations',
            label: [
                {
                    hint: 'JSON Array, holding the translations required by this Macroponent',
                    label: 'Required translations',
                    plural: 'Required translations',
                },
            ],
            maxLength: 8000,
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            maxLength: 32,
            primary: true,
        }),
        data: JsonColumn({
            label: [
                {
                    hint: 'JSON Object, describing each data item for this Macroponent',
                    label: 'Data',
                    plural: 'Data',
                },
            ],
            maxLength: 8000,
        }),
        disable_auto_reflow: BooleanColumn({
            default: false,
            label: 'Disable Auto Reflow',
            maxLength: 40,
        }),
        composition: JsonColumn({
            label: [
                {
                    hint: 'JSON Array, describing all the static elements of the Macroponent UI',
                    label: 'Composition',
                    plural: 'Compositions',
                },
            ],
            maxLength: 8000,
        }),
        component_dependencies: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Components used by this Macroponent',
                    label: 'Component dependencies',
                    plural: 'Component dependencies',
                },
            ],
            maxLength: 1024,
            referenceTable: 'sys_ux_lib_component',
        }),
        root_component_config: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'JSON Object, specifying the configuration of the root element for this Macropoent',
                    label: 'Root element configuration',
                    plural: 'Root element configurations',
                },
            ],
            maxLength: 8000,
        }),
        required_sys_props: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'String, specifying the system properties used in this macroponent. Separate multiple properties with commas (no quotes needed).',
                    label: 'Required System Properties',
                    plural: 'Required System Properties',
                },
            ],
            maxLength: 8000,
        }),
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            mandatory: true,
            label: 'Name',
            maxLength: 255,
        }),
        handled_events: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Events handled by the root element',
                    label: 'Handled Events',
                    plural: 'Handled Events',
                },
            ],
            maxLength: 4001,
            referenceTable: 'sys_ux_event',
        }),
        ext_controller_dep: JsonColumn({
            label: [
                {
                    hint: 'JSON Array, describing all the External Controller Dependencies',
                    label: 'External Controller Dependencies',
                    plural: 'External Controller Dependencies',
                },
            ],
            maxLength: 8000,
        }),
        style_config: JsonColumn({
            default: '{}',
            label: [
                {
                    hint: 'Macroponent level style block',
                    label: 'Style',
                    plural: 'Styles',
                },
            ],
            maxLength: 8000,
        }),
        state_properties: JsonColumn({
            label: [
                {
                    hint: 'JSON Array, holding any state the client has set for this Macroponent',
                    label: 'State',
                    plural: 'States',
                },
            ],
            maxLength: 8000,
        }),
        layout: JsonColumn({
            label: [
                {
                    hint: 'JSON Object, describing layout for this Macroponent',
                    label: 'Layout model',
                    plural: 'Layout models',
                },
            ],
            maxLength: 8000,
        }),
        category: ChoiceColumn({
            default: 'component',
            choices: {
                component: {
                    label: 'Component',
                    sequence: 100,
                },
                page: {
                    label: 'Page',
                    sequence: 200,
                },
                client_state_data_broker: {
                    label: 'Data Broker Proxy',
                    sequence: 300,
                },
                chrome: {
                    label: 'App Shell UI',
                    sequence: 400,
                },
                controller: {
                    label: 'Controller',
                    sequence: 600,
                },
                modal: {
                    label: 'Modal',
                    sequence: 600,
                },
                popover: {
                    label: 'Popover',
                    sequence: 650,
                },
                viewport: {
                    label: 'Viewport',
                    sequence: 700,
                },
                ui_controller: {
                    label: 'UI Controller',
                    sequence: 800,
                },
                primitives: {
                    label: 'Primitive',
                    sequence: 900,
                },
                sub_page: {
                    label: 'Sub Page',
                    sequence: 1000,
                },
                bundle: {
                    label: 'Bundle',
                    sequence: 1100,
                },
                modeless_dialog: {
                    label: 'Modeless Dialog',
                    sequence: 1200,
                },
                modeless_dialog_bundle: {
                    label: 'Modeless Dialog Bundle',
                    sequence: 1300,
                },
            },
            // In platform the dropdown value is 'dropdown_without_none' but we are using 'suggestion' to retain the
            // original choices and their intellisense while also allowing any string value. This is needed because
            // there are 52+ OOB records and other store apps with category values outside the defined choices, which
            // would otherwise cause validation errors post conversion or while upgrading the SDK.
            // Deliberate divergence from the instance: do not let a `now-sdk dependencies` type refresh put this
            // back to 'dropdown_without_none'.
            dropdown: 'suggestion',
            label: [
                {
                    hint: 'Macroponent Category',
                    label: 'Category',
                    plural: 'Categories',
                },
            ],
            maxLength: 40,
        }),
        schema_version: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: "javascript:gs.getProperty('com.glide.uxf.schema.version', '1.0.0')",
            label: [
                {
                    hint: 'Schema version used by this Macroponent',
                    label: 'Schema version',
                    plural: 'Schema versions',
                },
            ],
            mandatory: true,
            maxLength: 40,
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        form_factors: JsonColumn({
            default: '{}',
            label: [
                {
                    hint: 'Macroponent level custom form factors',
                    label: 'Form Factors',
                    plural: 'Form Factors',
                },
            ],
            maxLength: 8000,
        }),
        root_component: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Root element definition',
            maxLength: 32,
            referenceTable: 'sys_ux_lib_component',
        }),
        bundles: JsonColumn({
            label: [
                {
                    hint: 'JSON Array, describing all the bundles being used in this macroponent',
                    label: 'Bundles',
                    plural: 'Bundles',
                },
            ],
            maxLength: 8000,
        }),
        dispatched_events: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Events dispatched by the macroponent',
                    label: 'Dispatched Events',
                    plural: 'Dispatched Events',
                },
            ],
            maxLength: 4001,
            referenceTable: 'sys_ux_event',
        }),
        output_prop_mapping: JsonColumn({
            label: [
                {
                    hint: 'Maps internal binding values to external API',
                    label: 'Output Prop Mapping',
                    plural: 'Output Prop Mappings',
                },
            ],
            maxLength: 8000,
        }),
        interfaces: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Interfaces implemented by this macroponent',
                    label: 'Interfaces',
                    plural: 'Interfaces',
                },
            ],
            maxLength: 1024,
            referenceTable: 'sys_ux_interface',
        }),
        da_relay_models: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'This Macroponent will relay DA Client Actions from the specified Models, as its own Dispatched Events',
                    label: 'Action relay models',
                    plural: 'Action relay models',
                },
            ],
            maxLength: 1024,
            referenceTable: 'sys_declarative_action_model_definition',
        }),
        interactions: JsonColumn({
            label: [
                {
                    hint: 'JSON Array, describing interactive and automated behavior for this Macroponent',
                    label: 'Interactions',
                    plural: 'Interactions',
                },
            ],
            maxLength: 8000,
        }),
        macroponent_dependencies: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: [
                {
                    hint: 'Macroponents used by this Macroponent',
                    label: 'Macroponent dependencies',
                    plural: 'Macroponent dependencies',
                },
            ],
            maxLength: 1024,
            referenceTable: 'sys_ux_macroponent',
        }),
        extends: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Extends',
            maxLength: 32,
            referenceTable: 'sys_ux_macroponent',
        }),
        associated_types: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Associated types',
            maxLength: 1024,
            referenceTable: 'sys_ux_macroponent_type',
        }),
        internal_event_mappings: JsonColumn({
            label: 'Internal Event Mappings',
            maxLength: 8000,
        }),
        extension_point: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Extension Point',
            maxLength: 32,
            referenceTable: 'sys_ux_extension_point',
        }),
    },
    textIndex: true,
})
